'use strict';
const $ = (s, root = document) => root.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const iconPaths = {
 logo:'M4 7h6l3 5-3 5H4l3-5-3-5Zm10 0h6l-3 5 3 5h-6l-3-5 3-5Z',
 grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
 people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',
 mail:'M3 5h18v14H3zM3 5l9 8 9-8', chat:'M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5Z',
 campaign:'m3 11 18-7-5 17-4-7-9-3Zm9 3 9-10', calendar:'M3 5h18v16H3zM16 3v4M8 3v4M3 11h18',
 activity:'M2 12h4l3-9 6 18 3-9h4', settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',
 arrow:'M5 12h14m-5-5 5 5-5 5', chevron:'m9 5 7 7-7 7', plus:'M12 5v14M5 12h14', check:'m5 12 4 4L19 6',
 pause:'M8 5v14M16 5v14', play:'m7 4 14 8-14 8V4Z', close:'M6 6l12 12M6 18 12 6', external:'M15 3h6v6M10 14 11-11M21 14v7H3V3h7',
 shield:'m12 3 8 4v6c0 5-8 9-8 9s-8-4-8-9V7l8-4Zm-4 9 3 3 5-6', spark:'m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7L12 3Z',
 search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0Z', globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM3 12h18M12 3c4 4 4 14 0 18-4-4-4-14 0-18Z',
 local:'M3 4h18v13H3zM8 21h8M12 17v4', clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v5l3 2', warning:'m12 3 10 18H2L12 3ZM12 9v5M12 17v1',
 folder:'M3 5h7l2 3h9v13H3V5Z', coins:'M20 6c0 2-4 3-8 3S4 8 4 6s4-3 8-3 8 1 8 3ZM4 6v12c0 2 4 3 8 3s8-1 8-3V6M4 12c0 2 4 3 8 3s8-1 8-3',
 refresh:'M3 11a9 9 0 0 1 15-7l3 3M21 3v4h-4M21 13a9 9 0 0 1-15 7l-3-3M3 21v-4h4', menu:'M4 6h16M4 12h16M4 18h16'
};
const ico = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name] || iconPaths.folder}"/></svg>`;
const nav = [['overview','grid','Overview'],['prospects','people','Prospects'],['review','mail','Review inbox'],['sent','mail','Sent emails'],['conversations','chat','Conversations'],['campaigns','campaign','Campaigns'],['business','calendar','Meetings & projects'],['activity','activity','Activity'],['setup','settings','Setup & costs']];
const state = {snapshot:null, csrf:'', page:'overview', step:0, selectedMessage:null, selectedConversation:null, details:{}, models:[], providerDraft:null, dirty:false, filter:'', filterCampaign:'', busy:false};
const pretty = v => String(v ?? '').replaceAll('_',' ').toLowerCase().replace(/^./,c=>c.toUpperCase());
const date = v => v ? new Date(v).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}) : '—';
const money = v => new Intl.NumberFormat(undefined,{style:'currency',currency:'USD',maximumFractionDigits:2}).format(v||0);
function badge(text, tone='') { const inferred = /sent|done|won|completed|qualified|engaged|connected|ready|booked/i.test(text)?'green': /unknown|failed|dead|suppressed|bounced/i.test(text)?'red': /review|pending|awaiting|hold|research|running/i.test(text)?'amber':''; return `<span class="badge ${tone||inferred}"><i></i>${esc(pretty(text))}</span>`; }
function button(label,action,kind='',attrs=''){return `<button type="button" class="btn ${kind}" data-action="${action}" ${attrs}>${label}</button>`;}
function empty(icon,title,description,cta=''){return `<div class="empty">${ico(icon,'empty-icon')}<h3>${esc(title)}</h3><p>${esc(description)}</p>${cta}</div>`;}
function field(label,name,value='',type='text',extra=''){return `<label class="field"><span>${esc(label)}</span><input name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function area(label,name,value='',extra=''){return `<label class="field"><span>${esc(label)}</span><textarea name="${esc(name)}" ${extra}>${esc(value)}</textarea></label>`;}
const contact = id => state.snapshot.contacts.find(c=>c.id===Number(id));
const campaign = id => state.snapshot.campaigns.find(c=>c.id===id);
const labelContact = id => contact(id)?.company || contact(id)?.name || `Prospect #${id}`;
const pending = () => state.snapshot.messages.filter(m=>['REVIEW','APPROVED','UNKNOWN','SENDING','DRY_RUN'].includes(m.status));
async function api(path,data){const r=await fetch(path,{method:data===undefined?'GET':'POST',credentials:'same-origin',headers:data===undefined?{}:{'Content-Type':'application/json','X-Pipeline-CSRF':state.csrf},body:data===undefined?undefined:JSON.stringify(data)});let result;try{result=await r.json();}catch{throw new Error('The local app did not return a response. Check whether it is still running.');}if(!r.ok)throw new Error(result.error||'Could not complete this action');return result;}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',6500);}
async function refresh(renderPage=true){state.snapshot=await api('/api/snapshot');updateDeliveryStatus();if(state.page==='sent')await loadSent();if(renderPage)render();}
async function action(path,data,message='Saved'){const result=await api(path,data);state.dirty=false;await refresh(false);if(result.task_id)toast('Started. Follow progress in Activity.');else if(message)toast(message);render();return result;}
function modal(title,body){const d=$('#dialog');d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2>${button(ico('close'),'close-dialog','icon-btn','aria-label="Close dialog"')}</div>${body}`;d.showModal();d.scrollTop=0;const first=$('input:not([type=checkbox]),textarea,select',d);if(first)setTimeout(()=>first.focus({preventScroll:true}),50);}
function closeModal(){state.dirty=false;$('#dialog').close();}
function getForm(form){return Object.fromEntries(new FormData(form));}
function lines(text){return text.split('\n').map(x=>x.trim()).filter(Boolean);}
function safeURL(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#';}catch{return '#';}}
function readinessCount(){const r=state.snapshot.setup;return [r.model_tested,r.identity_complete,r.google_connected,!state.snapshot.settings.discovery_enabled||state.snapshot.settings.search_provider==='exa'||state.snapshot.settings.brave_api_key_present,r.ready_to_send&&r.cloud_email_allowed].filter(Boolean).length;}
function render(){const s=state.snapshot;if(!s)return;const page=nav.find(n=>n[0]===state.page)||nav[0];const n=pending().length;$('#app').innerHTML=`
<aside class="sidebar"><a class="brand" href="#overview"><span class="brand-mark">${ico('logo')}</span>pipeline<span class="brand-dot">.</span></a><div class="workspace"><span class="avatar">Y</span><div><strong>Your workspace</strong><small>Independent & intentional</small></div>${ico('chevron')}</div><div class="nav-caption">WORKSPACE</div><nav aria-label="Main navigation">${nav.map(([id,icon,label])=>`<a href="#${id}" class="nav-item ${state.page===id?'active':''}">${ico(icon)}<span>${label}</span>${id==='review'&&n?`<b class="nav-count">${n}</b>`:''}${id==='setup'&&readinessCount()<5?'<span class="nav-alert"></span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="local-badge">${ico('local')}<div><strong>Local-first. Yours.</strong><small>No dashboard subscription.</small></div></div><a href="https://ai.google.dev/gemini-api/docs/pricing" target="_blank" rel="noreferrer" class="sidebar-help">Model pricing & credits ${ico('external')}</a><div class="sidebar-footer"><span class="avatar small">Y</span><span>You · Solo workspace</span><span class="version">v0.2</span></div></div></aside>
<div class="main-shell"><header class="topbar"><div class="breadcrumb"><span class="mobile-brand">pipeline.</span><span class="desktop-only">Workspace</span><span class="desktop-only">/</span><strong>${page[2]}</strong></div><div class="top-actions"><span class="host-status"><i class="${s.worker.running?'online':''}"></i>${s.worker.running?'Worker active':'Worker stopped'}</span>${button(ico('refresh'),'refresh','icon-btn','aria-label="Refresh data"')}${button(ico(s.paused?'play':'pause')+`<span>${s.paused?'Resume':'Pause all'}</span>`,'pause-global',s.paused?'outline amber-btn':'outline','aria-label="'+(s.paused?'Resume all campaigns':'Pause all outbound sending')+'"')}</div></header>
<main id="main-content">${s.paused?`<div class="notice pause-notice">${ico('pause')}<div><strong>Outbound sending is paused.</strong> Research and inbox processing may continue. Resume when you’re ready.</div></div>`:''}${deliveryStatus()}${renderPage()}</main><footer class="page-footer"><span>${ico('shield')} Review first. Stay in control.</span><span>Updated ${date(s.generated_at)} · Local workspace</span></footer></div>`;}
function renderPage(){return ({overview:overview,prospects:prospects,review:review,sent:sentEmails,conversations:conversations,campaigns:campaigns,business:business,activity:activity,setup:setup}[state.page]||overview)();}
function updateDeliveryStatus(){const panel=document.querySelector('.delivery-status'),html=deliveryStatus();if(panel){const expanded=panel.querySelector('details')?.open;panel.outerHTML=html;if(expanded){const details=document.querySelector('.delivery-status details');if(details)details.open=true;}}else if(html){document.querySelector('#main-content')?.insertAdjacentHTML('afterbegin',html);}}
function deliveryStatus(){const d=state.snapshot.delivery;if(!d)return '';const c=d.counts,sent=c.SENT||0,queued=d.queued_count??((c.APPROVED||0)+(c.REVIEW||0)),sending=c.SENDING||0,attention=d.attention_count??d.attention.length;const complete=sent===d.total&&d.total>0;return `<section class="panel delivery-status ${complete?'delivery-complete':''}" role="status" aria-live="polite"><div class="delivery-summary"><div><h2>${complete?'Emails sent successfully':queued&&!state.snapshot.worker.running?'Sending stopped — worker is not running':'Latest send status'}</h2><p><strong>${sent} of ${d.total} sent successfully</strong> · ${queued} queued · ${sending} sending${attention?` · ${attention} need checking`:''}${c.CANCELLED?` · ${c.CANCELLED} cancelled`:''}</p></div><a href="#sent" class="text-link">View sent emails ${ico('arrow')}</a></div><p class="field-hint">Sent successfully means Gmail confirmed sending; it does not confirm the recipient read it.${queued&&!state.snapshot.worker.running?' The worker is stopped. Start it from Activity to continue.':''}${queued&&state.snapshot.paused?' Sending is paused. Resume from the top bar to continue.':''}</p>${queued&&!state.snapshot.worker.running?button('Start sending','worker-start','primary'):''}${d.waiting.filter(r=>r.error).length?`<p class="delivery-wait">${esc(d.waiting.find(r=>r.error).error)}.${d.waiting.find(r=>r.error).retry_at&&state.snapshot.worker.running?` Next scheduled check ${date(d.waiting.find(r=>r.error).retry_at)}.`:state.snapshot.worker.running?' Waiting for the worker to process this email.':' Start sending to continue.'}</p>`:''}${attention?`<p class="delivery-attention">${d.attention.map(r=>`${esc(r.email)}: ${r.status==='UNKNOWN'?'Gmail has not confirmed sending; held to prevent a duplicate.':esc(r.error||(r.job_status==='CANCELLED'?'Send workflow cancelled':r.job_status==='DEAD'?'Send workflow failed':pretty(r.status)))}`).join('<br>')} <a href="#activity">View activity</a> · <a href="#review">Review email status</a></p>`:''}${d.sent.length?`<details><summary>Recently confirmed sends</summary>${d.sent.map(r=>`<p>${esc(r.email)} · ${esc(r.subject)} · Sent ${date(r.sent_at)}</p>`).join('')}</details>`:''}</section>`;}
function heading(kicker,title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`;}
function overview(){const s=state.snapshot;const totals={qualified:0,contacted:0,positive_replies:0,meetings_booked:0,revenue:0,projects_won:0};s.campaigns.forEach(c=>Object.keys(totals).forEach(k=>totals[k]+=c.metrics[k]||0));return `
${heading('A CLEAR PATH TO YOUR NEXT CLIENT','Good work starts with<br>a conversation.','Find the right people. Start useful conversations. Make room for the work you love.',button(ico('plus')+' Add a prospect','add-prospect','primary'))}
${!s.setup.ready_to_send?`<a href="#setup" class="setup-banner"><div class="setup-banner-icon">${ico('spark')}</div><div><strong>Let’s get your workspace ready.</strong><p>Connect a model, add your identity, and link Google. You can do it all here.</p></div><span class="setup-progress">${readinessCount()} of 5 ready</span><span class="link-button">Continue setup ${ico('arrow')}</span></a>`:''}
<div class="stat-grid">${[['Qualified prospects',totals.qualified,'people','Good fit, backed by research'],['Conversations started',totals.contacted,'chat','Unique prospects contacted'],['Positive replies',totals.positive_replies,'mail','Interest, not every response'],['Revenue recorded',money(totals.revenue),'coins',`${totals.projects_won} projects won`]].map(([title,value,icon,sub])=>`<div class="stat"><div class="stat-title">${title}${ico(icon)}</div><div class="stat-value">${value}</div><small>${sub}</small></div>`).join('')}</div>
<div class="overview-columns"><section class="panel"><div class="panel-head"><div><h2>Your next best move</h2><p>One useful action beats a busy pipeline.</p></div><span class="badge amber">FOCUS</span></div>${s.escalations.length?`<div class="next-action"><span class="action-symbol">${ico('chat')}</span><div><h3>${s.escalations.length} conversation${s.escalations.length!==1?'s':''} need your attention</h3><p>Review interested replies, questions, and decisions that need your judgment.</p><a href="#conversations" class="text-link">Open conversations ${ico('arrow')}</a></div></div>`:!s.setup.ready_to_send?`<div class="next-action"><span class="action-symbol">${ico('settings')}</span><div><h3>A few connections. Then you’re off.</h3><p>Choose a free local model or use your Gemini credits. Nothing sends until you approve it.</p><a href="#setup" class="text-link">Set up your workspace ${ico('arrow')}</a></div></div>`:pending().length?`<div class="next-action"><span class="action-symbol">${ico('mail')}</span><div><h3>Review your next conversation starter.</h3><p>Check the research and email before it joins the sending queue.</p><a href="#review" class="text-link">Review ${pending().length} message${pending().length!==1?'s':''} ${ico('arrow')}</a></div></div>`:`<div class="next-action"><span class="action-symbol">${ico('people')}</span><div><h3>Start with one business you can help.</h3><p>Add a company URL. Pipeline will research it and prepare a grounded draft.</p>${button('Add your first prospect '+ico('arrow'),'add-prospect','text-btn')}</div></div>`}<div class="mini-flow"><div><span>01</span><strong>Find a real fit</strong><small>Research with sources</small></div>${ico('chevron')}<div><span>02</span><strong>Make it personal</strong><small>Review every first step</small></div>${ico('chevron')}<div><span>03</span><strong>Have a conversation</strong><small>Focus on useful work</small></div></div></section>
<section class="panel budget-panel"><div class="panel-head"><div><h2>Small footprint.<br>Clear limits.</h2></div>${ico('local')}</div><div class="budget-number">${s.usage.calls}<span> / ${s.usage.limit}</span></div><p>model calls today <span class="utc-label">UTC</span></p><progress value="${s.usage.calls}" max="${Math.max(1,s.usage.limit)}" aria-label="Daily model calls"></progress><div class="budget-meta"><span>${s.usage.local?'Local model · no API fee':pretty(s.settings.provider)+' · your API account'}</span><strong>${s.usage.local?'On your computer':s.usage.estimated_usd===null?'Usage tracked':money(s.usage.estimated_usd)+' est.'}</strong></div><a href="#setup" class="text-link">Manage models & limits ${ico('arrow')}</a></section></div>
<div class="section-heading"><h2>Two ways to create value</h2><a href="#campaigns" class="text-link">Manage campaigns ${ico('arrow')}</a></div><div class="campaign-grid">${s.campaigns.map(c=>campaignCard(c,true)).join('')}</div>
<section class="panel recent-panel"><div class="panel-head"><div><h2>Recent activity</h2><p>The full picture, without the noise.</p></div><a href="#activity" class="text-link">View all ${ico('arrow')}</a></div>${s.audit.filter(a=>!a.event.startsWith('campaign.configured')).slice(0,4).map(a=>`<div class="timeline-row"><span class="timeline-dot"></span><div><strong>${esc(pretty(a.event.replaceAll('.',' ')))}</strong><small>${esc(a.entity)}</small></div><time>${date(a.created_at)}</time></div>`).join('')||`<div class="quiet-empty">${ico('clock')}<p>A clean slate. Your research, approvals, and conversations will appear here.</p></div>`}</section>`;}
function campaignCard(c,compact=false){const config=c.config;return `<article class="panel campaign-card"><div class="campaign-card-top"><span class="campaign-symbol ${config.id.includes('engineering')?'blue':''}">${ico(config.id.includes('engineering')?'spark':'campaign')}</span><div>${badge(c.paused?'Paused':config.mode==='AUTONOMOUS'?(c.authorized?'Autonomous':'Authorization needed'):config.mode)}</div></div><h3>${esc(config.name)}</h3><p>${esc(config.offer)}</p><div class="campaign-numbers"><div><strong>${c.metrics.qualified}</strong><small>Qualified</small></div><div><strong>${c.metrics.contacted}</strong><small>Contacted</small></div><div><strong>${c.metrics.positive_replies}</strong><small>Interested</small></div></div><div class="campaign-card-footer"><span>${config.daily_limit}/day · ${config.offer_hours}h offer limit</span>${button('Manage '+ico('arrow'),'edit-campaign','text-btn',`data-id="${esc(c.id)}"`)}</div>${!compact?`<div class="card-actions">${button(ico(c.paused?'play':'pause')+(c.paused?'Resume':'Pause'),'pause-campaign','outline',`data-id="${esc(c.id)}"`)}${config.mode==='AUTONOMOUS'&&!c.authorized?button('Authorize live campaign','authorize-campaign','outline',`data-id="${esc(c.id)}"`):''}</div>`:''}</article>`;}
function prospects(){
 const s=state.snapshot,pool=s.prospect_pool||{contacts:s.contacts.length,target:120,sent:0};
 const drafts=s.messages.filter(m=>m.status==='REVIEW'&&campaign(m.campaign_id)?.config_hash===m.config_hash).length;
 const auto=s.campaigns.filter(c=>c.config.auto_draft);
 return `${heading('FREE HELP. REAL RELATIONSHIPS.','Review your prospects.','Click a company or its Review button to see the person, evidence and email.',button(ico('search')+' Find prospects','find-prospects','primary')+button(ico('plus')+' Add URL','add-prospect','outline'))}
 <div class="stat-grid prospect-stats">
 <div class="stat"><div class="stat-title">Prospect pool ${ico('people')}</div><div class="stat-value">${pool.contacts}<span class="pool-target"> / ${pool.target}</span></div><progress value="${pool.contacts}" max="${Math.max(1,pool.target)}" aria-label="Prospect pool goal"></progress><small>Distinct people retained for review</small></div>
 <div class="stat"><div class="stat-title">Emails ready to review ${ico('mail')}</div><div class="stat-value">${drafts}</div><a href="#review" class="text-link">Open review inbox ${ico('arrow')}</a></div>
 <div class="stat"><div class="stat-title">People reached ${ico('chat')}</div><div class="stat-value">${pool.sent}</div><small>Emails send only after your approval</small></div></div>
 ${bulkSend()}<section class="panel prospect-automation"><div><strong>${s.settings.discovery_enabled?'Automatic discovery enabled':'Discovery paused'}</strong><p>${s.worker.running?'Worker active':'Worker stopped'} · Checks every ${s.settings.discovery_interval_hours||4} hour${s.settings.discovery_interval_hours===1?'':'s'} · ${auto.length?'Automatic drafts above each campaign’s fit threshold':'Drafts prepared when you select a prospect'}</p></div><div class="form-actions">${button('Generate eligible drafts','queue-prospect-drafts','outline')}${!s.worker.running?button('Start worker','worker-start','outline'):''}</div></section>
 <section class="panel prospect-list"><div class="table-toolbar prospect-toolbar"><div class="search-box">${ico('search')}<input id="prospect-search" aria-label="Search prospects" placeholder="Search company or person…" value="${esc(state.filter)}"></div><select id="prospect-view" aria-label="Filter prospect status">${[['all','All prospects'],['drafts','Ready emails'],['queued','Approved / queued'],['sent','Sent emails'],['undrafted','No email yet'],['research','Needs research']].map(([v,l])=>`<option value="${v}" ${(state.prospectView||'all')===v?'selected':''}>${l}</option>`).join('')}</select><select id="prospect-campaign" aria-label="Filter campaign"><option value="">All campaigns</option>${s.campaigns.map(c=>`<option value="${esc(c.id)}" ${state.filterCampaign===c.id?'selected':''}>${esc(c.config.name)}</option>`).join('')}</select></div><div id="prospect-table">${prospectTable()}</div></section>
 <details class="panel prospect-discovery-details"><summary>Discovery activity & search history</summary><div class="panel-head"><div><h2>Automatic prospect discovery</h2><p>Free search, published contacts and your existing model budget.</p></div></div>${(s.discovery_reports||[]).map(r=>`<div class="timeline-row"><div><strong>${esc(campaign(r.campaign_id)?.config.name||r.campaign_id)} · ${esc(r.status)}</strong><p>${r.contacts} new contacts · ${r.duplicates} known results · ${r.candidates} companies checked</p><small>${esc(r.stop_reason||r.error||'')}</small></div><time>${date(r.finished_at||r.started_at)}</time></div>`).join('')}<div class="discovery-query-list">${(s.discovery_query_history||[]).slice(0,8).map(q=>`<p>${esc(q.query)}<small>${q.contacts} new contacts · ${q.duplicates} known results</small></p>`).join('')}</div></details>
 <section class="panel prospect-research"><div class="panel-head"><div><h2>Companies to research further</h2><p>No usable email yet, or a source needs another attempt.</p></div>${badge((s.discovery_candidates||[]).length+' companies')}</div>${(s.discovery_candidates||[]).map(c=>`<div class="timeline-row"><div><a href="${safeURL(c.url)}" target="_blank" rel="noreferrer"><strong>${esc(c.domain)}</strong></a><small>${esc(c.reason||pretty(c.status))}</small></div>${button('Research again','research-candidate','outline',`data-id="${c.id}"`)}</div>`).join('')||'<p class="panel-empty">No companies waiting for additional research.</p>'}</section>`;
}
function prospectTable(){
 const view=state.prospectView||'all';
 const rows=state.snapshot.contacts.filter(c=>(!state.filter||`${c.company} ${c.email} ${c.name}`.toLowerCase().includes(state.filter.toLowerCase()))&&(!state.filterCampaign||state.filterCampaign===c.campaign_id)&&(view==='all'||view==='drafts'&&['REVIEW','APPROVED'].includes(c.draft_status)||view==='queued'&&c.draft_status==='APPROVED'||view==='sent'&&c.sent_count>0||view==='undrafted'&&!c.draft_message_id||view==='research'&&c.state==='NEEDS_RESEARCH'));
 return rows.length?`<div class="table-scroll prospect-table-wrap"><table class="prospect-table"><thead><tr><th>Company / person</th><th>Fit</th><th>Email & review</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${rows.map(c=>{
 const cfg=campaign(c.campaign_id)?.config;
 const draftLabel=c.draft_status==='STALE'?'Needs regeneration':c.draft_status==='REVIEW'?'Email ready':c.draft_status?pretty(c.draft_status):c.draft_eligible&&cfg?.auto_draft&&c.score>=cfg.auto_draft_threshold?'Draft queued':c.state==='NEEDS_RESEARCH'?'Needs research':'No email yet';
 return `<tr class="prospect-row" data-action="inspect-contact" data-id="${c.id}"><td><button type="button" class="prospect-name">${esc(c.company)}</button><small>${esc(c.name||c.email)}</small><small class="prospect-campaign-label">${esc(campaign(c.campaign_id)?.config.name||c.campaign_id)}</small></td><td class="prospect-fit"><span class="fit-score">${c.score==null?'—':Math.round(c.score*100)+'%'}</span><small>fit</small></td><td class="prospect-status">${badge(draftLabel)}<small>${c.region_reviewed?'US location confirmed':'US confirmation needed before sending'}</small>${c.feedback?'<small>'+esc(pretty(c.feedback.verdict))+'</small>':''}</td><td class="prospect-review-cell">${button('Review '+ico('arrow'),'inspect-contact','outline prospect-review',`data-id="${c.id}" aria-label="Review ${esc(c.company)}"`)}</td></tr>`;
 }).join('')}</tbody></table></div><div class="table-foot">${rows.length} prospects · Click a company to review · Latest prospects plus all pending recipients</div>`:empty('people','No prospects in this view.','Choose another filter or find more people to help.',button('Find prospects','find-prospects','primary'));
}
function bulkSend(){const s=state.snapshot,n=s.prepared_count??s.messages.filter(m=>['REVIEW','APPROVED'].includes(m.status)).length;const r=state.bulkResult;return `<section class="panel bulk-send"><div><h2>Send prepared emails</h2><p>All campaigns · ${n} prepared. Starts the worker and sends gradually within your configured limits. Rate limits retry automatically.</p></div><form id="bulk-send-form" class="form-stack"><label class="check-field"><input type="checkbox" name="confirm" required><span>I confirm all recipients in this batch are in the United States and authorize sending these emails.</span></label><button type="submit" class="btn primary" ${!n||s.paused||!s.setup.ready_to_send?'disabled':''}>${ico('mail')} Approve & send all (${n})</button></form>${s.paused?'<p class="field-hint">Resume sending from the top bar first.</p>':!s.setup.ready_to_send?'<p class="field-hint">Complete Setup & costs before sending.</p>':''}${r?`<div class="bulk-send-result" role="status"><p>${r.approved.length} emails approved and queued. ${r.skipped.length} skipped.${r.worker?.running?' Worker active.':''}</p>${r.worker_error?`<p>Emails are saved in the queue, but the worker could not start: ${esc(r.worker_error)}. Start it from Activity.</p>`:''}${r.skipped.length?`<details><summary>View skipped emails</summary>${r.skipped.map(item=>`<p>${esc(item.email)}: ${esc(item.reason)}</p>`).join('')}</details>`:''}</div>`:''}</section>`;}
function review(){const messages=pending().filter(m=>!state.reviewFilter||state.reviewFilter==='all'||state.reviewFilter==='ready'&&['REVIEW','APPROVED'].includes(m.status)&&campaign(m.campaign_id)?.config_hash===m.config_hash||state.reviewFilter==='queued'&&m.status==='APPROVED'||state.reviewFilter==='attention'&&['UNKNOWN','SENDING'].includes(m.status));let selected=messages.find(m=>m.id===state.selectedMessage)||messages[0];if(selected)state.selectedMessage=selected.id;return `${heading('YOUR VOICE, YOUR CALL','A thoughtful first impression.','Review the email, confirm the recipient is in the US, and queue it here.')}${bulkSend()}<div class="email-view-toolbar"><label class="field"><span>Filter emails</span><select id="review-filter" aria-label="Filter emails">${[['all','All pending emails'],['ready','Ready emails'],['queued','Approved / queued'],['attention','Sending / needs reconciliation']].map(([v,l])=>`<option value="${v}" ${(state.reviewFilter||'all')===v?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="review-layout"><section class="panel message-list"><div class="list-title">Needs attention <span>${messages.length}</span></div>${messages.map(m=>`<button class="message-item ${selected?.id===m.id?'selected':''}" data-action="select-message" data-id="${m.id}"><span class="message-avatar">${esc(labelContact(m.contact_id).slice(0,1))}</span><span><strong>${esc(labelContact(m.contact_id))}</strong><span class="message-subject">${esc(m.subject)}</span><small>${esc(pretty(m.category))} · ${date(m.created_at)}</small></span>${badge(m.status)}</button>`).join('')||'<div class="list-empty">No messages waiting.<br>Quality over a full inbox.</div>'}</section><section class="panel message-detail">${selected?messageDetail(selected):empty('mail','Your review inbox is clear.','When a prospect qualifies, its email will appear here with the research and editing checks.',button('Find a prospect '+ico('arrow'),'add-prospect','primary'))}</section></div>`;}
function messageDetail(m){const c=contact(m.contact_id),config=campaign(m.campaign_id);let audit={};try{audit=JSON.parse(m.edit_audit);}catch{}const details=state.details[m.contact_id];const reasons=[];if(!state.snapshot.setup.google_connected)reasons.push('Connect Google before sending.');if(!state.snapshot.setup.identity_complete)reasons.push('Complete your sender identity.');if(config?.config_hash!==m.config_hash)reasons.push('Campaign settings changed. Regenerate this draft.');if(c?.takeover)reasons.push('This conversation is under manual takeover.');if(c?.reply_hold&&['initial','followup'].includes(m.category))reasons.push('A reply has stopped automated outreach.');const canApprove=m.status==='REVIEW'&&!reasons.length;return `<div class="message-detail-head"><div>${badge(m.category)}<span class="muted">${esc(config?.config.name)}</span></div><div class="email-recipient"><span class="message-avatar large">${esc((c?.name||c?.company||'?').slice(0,1))}</span><div><h2>${esc(c?.name||c?.company||'Prospect')}</h2><span>${esc(c?.email||'')} · ${esc(c?.company||'')}</span></div></div><h3 class="email-subject">${esc(m.subject)}</h3></div><pre class="email-body">
${esc(m.body)}</pre><div class="quality-strip">${audit.manual_edit?`<span>${ico('check')} Edited by hand</span><span>Review your changes before sending</span>`:`<span>${ico('check')} no-ai-slop edited</span><span>${ico('shield')} Grounding ${Math.round((audit.grounding?.confidence||0)*100)}%</span>`}<span>${ico('mail')} Plain text</span></div><details class="evidence-details"><summary>Research & editing notes ${ico('chevron')}</summary><p>${esc(audit.changes||'Editing audit recorded.')}</p>${details?details.research.evidence.map(e=>`<blockquote>${esc(e.quote)}<a href="${safeURL(e.url)}" target="_blank" rel="noreferrer">View source ${ico('external')}</a></blockquote>`).join(''):button('Load source evidence','load-evidence','outline',`data-id="${m.contact_id}"`)}</details>${reasons.length?`<div class="notice compact">${ico('warning')}<div>${reasons.map(r=>`<p>${esc(r)}</p>`).join('')}</div></div>`:''}<div class="message-actions">${['UNKNOWN','SENDING'].includes(m.status)?button('Reconcile with Gmail','reconcile','outline',`data-id="${m.id}"`):`${['REVIEW','APPROVED','DRY_RUN'].includes(m.status)?button('Edit email','edit-message','outline',`data-id="${m.id}"`):''}${button('Discard','reject-message','ghost',`data-id="${m.id}"`)}${button('Regenerate','redraft','outline',`data-id="${m.contact_id}" ${c?.state!=='READY_FOR_OUTREACH'?'disabled':''}`)}${m.status==='APPROVED'?badge('Approved · queued'): `<form id="approve-form" class="form-stack"><input type="hidden" name="id" value="${esc(m.id)}"><label class="check-field"><input type="checkbox" name="confirm" required><span>I confirm this recipient is in the United States and authorize sending this email.</span></label><details class="advanced"><summary>Additional notes · optional</summary>${area('Business relevance · optional','legal_basis',details?.research.legal_basis||'','rows="2"')}${area('Source notes · optional','provenance',details?.research.provenance||'','rows="2"')}</details><button type="submit" class="btn primary" ${canApprove?'':'disabled'}>${ico('check')} Approve & send email</button></form>`}`}<small>${state.snapshot.worker.running?'Approved mail can be sent by the active worker.':'Approving starts sending automatically, within your configured limits.'}</small></div>`;}
async function loadSent(){const request=(state.sentRequest||0)+1;state.sentRequest=request;const result=await api('/api/messages/sent',{offset:state.sentOffset||0,search:state.sentSearch||'',campaign_id:state.sentCampaign||''});if(state.sentRequest===request){state.sentData=result;state.sentOffset=result.offset;}}
function sentEmails(){const d=state.sentData;const messages=d?.messages||[];const selected=messages.find(m=>m.id===state.selectedSent)||messages[0];if(selected)state.selectedSent=selected.id;return `${heading('EMAIL HISTORY','Sent emails','Every email sent through Pipeline, with its recipient, send time, and original message.')}<form id="sent-search-form" class="email-view-toolbar"><label class="field"><span>Search sent emails</span><input name="search" aria-label="Search sent emails" value="${esc(state.sentSearch||'')}" placeholder="Recipient, company, subject or email text"></label><label class="field"><span>Campaign</span><select name="campaign_id" aria-label="Filter sent campaign"><option value="">All campaigns</option>${state.snapshot.campaigns.map(c=>`<option value="${esc(c.id)}" ${state.sentCampaign===c.id?'selected':''}>${esc(c.config.name)}</option>`).join('')}</select></label><button type="submit" class="btn outline">Search</button></form><div class="review-layout"><section class="panel message-list"><div class="list-title">Sent <span>${d?.total??'…'}</span></div>${messages.map(m=>`<button class="message-item ${selected?.id===m.id?'selected':''}" data-action="select-sent" data-id="${esc(m.id)}"><span class="message-avatar">${esc((m.company||m.email).slice(0,1))}</span><span><strong>${esc(m.company)}</strong><span class="message-subject">${esc(m.subject)}</span><small>${esc(m.email)} · ${date(m.sent_at)}</small></span>${badge('Sent')}</button>`).join('')||`<div class="list-empty">${d?'No sent emails match this view.':'Loading sent emails…'}</div>`}</section><section class="panel message-detail">${selected?`<div class="message-detail-head">${badge('Sent')}<span class="muted">${esc(selected.campaign_name)}</span><div class="email-recipient"><div><h2>${esc(selected.name||selected.company)}</h2><span>To: ${esc(selected.email)}</span></div></div><h3 class="email-subject">${esc(selected.subject)}</h3><p class="muted">Sent ${esc(new Date(selected.sent_at).toLocaleString())} · ${esc(pretty(selected.category))}</p></div><pre class="email-body">${esc(selected.body)}</pre>`:empty('mail','Your sent email history.','Emails appear here after Gmail confirms they were sent.')}</section></div>${d?`<div class="email-pagination"><span>${d.total?d.offset+1:0}–${d.offset+messages.length} of ${d.total} emails</span>${button('Previous','sent-previous','outline',d.offset===0?'disabled':'')}${button('Next','sent-next','outline',d.offset+messages.length>=d.total?'disabled':'')}</div>`:''}`;}
function conversations(){const s=state.snapshot;const contacts=s.contacts.filter(c=>s.inbound.some(i=>i.contact_id===c.id)||['ENGAGED','MEETING_BOOKED','PROPOSAL_SENT','WON','PROJECT_COMPLETED'].includes(c.state));let c=contacts.find(c=>c.id===state.selectedConversation)||contacts[0];return `${heading('MAKE ROOM FOR THE HUMAN PART','Real replies.<br>Real possibilities.','Follow the context, answer with care, and know when to take over.',button(ico('refresh')+' Sync inbox','poll','outline',s.setup.google_connected?'':'disabled'))}<div class="review-layout"><section class="panel message-list"><div class="list-title">Conversations <span>${contacts.length}</span></div>${contacts.map(row=>`<button class="message-item ${c?.id===row.id?'selected':''}" data-action="select-conversation" data-id="${row.id}"><span class="message-avatar">${esc(row.company.slice(0,1))}</span><span><strong>${esc(row.company)}</strong><small>${esc(row.email)}</small></span>${badge(row.state)}</button>`).join('')||'<div class="list-empty">Replies will appear here.<br>Follow-ups stop as soon as one arrives.</div>'}</section><section class="panel conversation-detail">${c?`<div class="panel-head"><div><h2>${esc(c.company)}</h2><p>${esc(c.email)}</p></div>${badge(c.takeover?'Manual takeover':c.state)}</div><div class="thread">${[...s.messages.filter(m=>m.contact_id===c.id&&m.status==='SENT').map(m=>({body:m.body,at:m.sent_at,out:true,status:'Sent'})),...s.inbound.filter(i=>i.contact_id===c.id).map(i=>({body:i.body,at:i.received_at,out:false,status:i.classification||'Classifying'}))].sort((a,b)=>new Date(a.at)-new Date(b.at)).map(m=>`<div class="thread-message ${m.out?'outbound':''}"><div><strong>${m.out?'You':esc(c.name||c.company)}</strong><span>${esc(pretty(m.status))} · ${date(m.at)}</span></div><pre>${esc(m.body)}</pre></div>`).join('')}</div><div class="conversation-actions">${button('Draft a response','respond','primary',`data-id="${c.id}" ${c.takeover?'disabled':''}`)}${button('Plan a meeting','meeting','outline',`data-id="${c.id}" ${s.setup.google_connected?'':'disabled'}`)}${button('Take over manually','takeover','ghost',`data-id="${c.id}" ${c.takeover?'disabled':''}`)}</div><div class="conversation-bottom"><p>${ico('shield')} A reply keeps follow-ups on hold. Pricing and scope decisions need you.</p>${button('Prepare a proposal','proposal','text-btn',`data-id="${c.id}"`)}</div>`:empty('chat','The conversation is the point.','Interested replies, questions, and ambiguous messages appear here, with follow-ups already on hold.')}</section></div><section class="panel recent-panel"><div class="panel-head"><div><h2>Needs your judgment</h2><p>Decisions that deserve a human.</p></div>${badge(s.escalations.length+' open')}</div>${s.escalations.length?s.escalations.map(e=>`<div class="escalation-row"><span class="action-symbol small">${ico('chat')}</span><div><strong>${e.contact_id?esc(labelContact(e.contact_id)):'Workflow attention'}</strong><p>${esc(e.reason)}</p></div>${button('Mark resolved','resolve-escalation','outline',`data-id="${e.id}"`)}</div>`).join(''): '<div class="quiet-empty">Nothing needs your judgment right now.</div>'}</section>`;}
function campaigns(){return `${heading('FOCUSED OFFERS. SHARED MOMENTUM.','A clear offer for<br>each kind of customer.','Campaigns share the engine. Their targets, limits, offers, and results stay separate.',button(ico('plus')+' New campaign','new-campaign','primary'))}<div class="campaign-grid">${state.snapshot.campaigns.map(c=>campaignCard(c)).join('')}</div><div class="notice">${ico('shield')}<div><strong>Your limits stay yours.</strong><p>Changing a campaign invalidates its old message approvals and autonomous authorization. Regenerate unsent drafts after an edit.</p></div></div>`;}
function business(){const s=state.snapshot;return `${heading('FROM FIRST CALL TO FINISHED WORK','Turn interest into<br>something useful.','Confirm meetings, agree on bounded work, and keep a record of the value delivered.')}<div class="business-columns"><section class="panel"><div class="panel-head"><h2>Meetings</h2>${badge(s.meetings.filter(m=>m.status==='BOOKED').length+' booked')}</div>${s.meetings.length?s.meetings.map(m=>`<div class="business-row"><span class="date-icon">${new Date(m.start).toLocaleDateString(undefined,{month:'short'})}<strong>${new Date(m.start).getDate()}</strong></span><div><h3>${esc(labelContact(m.contact_id))}</h3><p>${date(m.start)} · ${Math.round((new Date(m.end)-new Date(m.start))/60000)} min</p>${badge(m.status)}</div>${m.status==='BOOKED'?button('Completed','complete-meeting','outline',`data-id="${m.contact_id}"`):''}</div>`).join(''):empty('calendar','Your next good conversation.','Agreed meetings will appear here. Offer fresh slots from a conversation.')}</section><section class="panel"><div class="panel-head"><h2>Opportunities</h2>${badge(s.opportunities.length+' total')}</div>${s.opportunities.length?s.opportunities.map(o=>`<div class="opportunity"><div><h3>${esc(labelContact(o.contact_id))}</h3>${badge(o.status)}</div>${o.proposal?`<p>${esc(JSON.parse(o.proposal).scope)}</p><span class="muted">${JSON.parse(o.proposal).hours} hours proposed · needs scope approval</span>`:'<p>Discuss the actual problem and a bounded next step.</p>'}<div class="card-actions">${button(o.proposal?'View / redraft proposal':'Draft proposal','proposal','outline',`data-id="${o.contact_id}"`)}${o.proposal&&o.status!=='WON'?button('Record agreed project','win','primary',`data-id="${o.contact_id}"`):''}</div></div>`).join(''):empty('folder','Keep the next step concrete.','Interested replies create opportunities. Proposals stay internal until you approve the scope.')}</section></div><section class="panel recent-panel"><div class="panel-head"><div><h2>Projects & outcomes</h2><p>Record what happened. Use measured results to decide what comes next.</p></div></div>${s.projects.length?`<div class="table-scroll"><table><thead><tr><th>Project</th><th>Status</th><th>Hours</th><th>Revenue</th><th>Customer value</th><th></th></tr></thead><tbody>${s.projects.map(p=>{const o=s.opportunities.find(o=>o.id===p.opportunity_id);return `<tr><td><strong>${esc(labelContact(o?.contact_id))}</strong><small>${p.free?'Bounded free project':'Paid project'}</small></td><td>${badge(p.status)}</td><td>${p.hours}</td><td>${money(p.revenue)}</td><td>${esc(p.customer_value||'Not recorded')}</td><td>${p.status==='ACTIVE'?button('Record completion','complete-project','outline',`data-id="${p.id}"`):button('Results & feedback','project-feedback','outline',`data-id="${p.id}"`)}</td></tr>`;}).join('')}</tbody></table></div>`:empty('coins','Useful work is the outcome.','When a real project is agreed, track hours, revenue, customer feedback, and verified results here.')}</section>`;}
function activity(){const s=state.snapshot;const failures=s.jobs.filter(j=>j.status==='DEAD'||j.error);return `${heading('A SYSTEM YOU CAN READ','Know what happened.<br>Know what’s next.','Research, workflow progress, and recoverable failures, in one place.',button(ico(s.worker.running?'pause':'play')+(s.worker.running?'Stop worker':'Start worker'),s.worker.running?'worker-stop':'worker-start','outline'))}<div class="activity-status"><div class="panel"><span class="host-status"><i class="${s.worker.running?'online':''}"></i>${s.worker.running?'Worker active':'Worker stopped'}</span><p>${s.worker.external?'Managed by your terminal or system service.':s.worker.owned?'Started and managed by this app.':'Start it from here to process queued actions.'}</p><small>Last heartbeat: ${date(s.worker.heartbeat_at)}</small></div><div class="panel"><span class="stat-value small">${s.jobs.filter(j=>j.status==='PENDING').length}</span><p>Pending workflow actions</p><small>Approval and pause gates can keep a task waiting.</small></div><div class="panel"><span class="stat-value small">${failures.length}</span><p>Tasks with something to inspect</p><small>Ambiguous sends always need reconciliation.</small></div></div>${s.local_model_progress?`<div class="notice compact">${ico('local')}<p>Local model: ${esc(s.local_model_progress.status)}${s.local_model_progress.percent!==null?' · '+s.local_model_progress.percent+'%':''}</p></div>`:''}${s.background.length?`<section class="panel recent-panel"><div class="panel-head"><h2>Actions you started</h2></div>${s.background.slice().reverse().map(t=>`<div class="background-task"><div><strong>${esc(t.name)}</strong>${badge(t.status)}<small>${date(t.started_at)}</small></div>${t.error?`<div class="notice compact">${esc(t.error)}</div>`:''}${t.result?`<details><summary>View result</summary><pre class="result-json">${esc(JSON.stringify(t.result,null,2))}</pre></details>`:''}</div>`).join('')}</section>`:''}<section class="panel recent-panel"><div class="panel-head"><h2>Workflow execution</h2></div>${s.jobs.length?`<div class="table-scroll"><table><thead><tr><th>Task</th><th>Status</th><th>Attempts</th><th>Due / next try</th><th>Details</th><th></th></tr></thead><tbody>${s.jobs.map(j=>`<tr><td><strong>${esc(pretty(j.kind))}</strong><small class="truncate">${esc(j.id)}</small></td><td>${badge(j.status)}</td><td>${j.attempts}</td><td>${date(j.due_at)}</td><td>${esc(j.error||'—')}</td><td>${['DEAD','CANCELLED'].includes(j.status)?button('Replay','replay','outline',`data-id="${esc(j.id)}"`):''}</td></tr>`).join('')}</tbody></table></div>`:empty('activity','Nothing is running in the background.','You can finish setup and inspect the app before starting the worker.')}</section><section class="panel recent-panel"><div class="panel-head"><h2>Audit trail</h2><span class="muted">Latest 100 events</span></div>${s.audit.map(a=>`<div class="timeline-row"><span class="timeline-dot"></span><div><strong>${esc(pretty(a.event.replaceAll('.',' ')))}</strong><small>${esc(a.entity)}</small></div><time>${date(a.created_at)}</time></div>`).join('')||'<div class="quiet-empty">No events recorded.</div>'}</section>`;}
const steps=[['Your model','Free local or Gemini credits'],['Your identity','The person behind the email'],['Google account','Email & calendar, connected'],['Discovery & limits','Keep costs predictable'],['Ready to launch','Review before you send']];
function setup(){const r=state.snapshot.setup;const complete=[r.model_tested,r.identity_complete,r.google_connected,!state.snapshot.settings.discovery_enabled||state.snapshot.settings.search_provider==='exa'||state.snapshot.settings.brave_api_key_present,r.ready_to_send&&r.cloud_email_allowed];return `${heading('YOUR WORKSPACE, ON YOUR TERMS','A little setup.<br>A lot less busywork.','Connect the essentials once. See exactly what is ready, what is missing, and what it costs.')}<div class="setup-layout"><aside class="setup-steps"><div class="setup-step-label">GETTING STARTED</div>${steps.map(([title,sub],i)=>`<button class="setup-step ${i===state.step?'current':''} ${complete[i]?'complete':''}" data-action="setup-step" data-step="${i}"><span>${complete[i]?ico('check'):i+1}</span><div><strong>${title}</strong><small>${sub}</small></div>${i===state.step?ico('chevron'):''}</button>`).join('')}<div class="setup-assurance">${ico('shield')}<strong>Nothing sends during setup.</strong><p>Your workspace starts in review mode. Connection tests never send an email.</p></div></aside><section class="panel setup-content">${[modelSetup,identitySetup,googleSetup,discoverySetup,launchSetup][state.step]()}</section></div>`;}
function setupTitle(n,title,desc){return `<div class="setup-panel-head"><div class="eyebrow">STEP ${n} OF 5</div><h2>${title}</h2><p>${desc}</p></div>`;}
function stepFooter(next=true){return `<div class="setup-footer"><span>Saved settings apply to the worker too.</span>${next?button('Continue '+ico('arrow'),'next-step','outline'):''}</div>`;}
function modelSetup(){const s=state.snapshot;const p=state.providerDraft||s.settings;return `${setupTitle(1,'Choose the brain. Keep the bill small.','Use your Gemini API credits, or run an open model on your own computer. You can switch later.')}<div class="provider-cards"><button class="provider-card ${p.provider==='gemini'?'chosen':''}" data-action="choose-provider" data-provider="gemini"><span class="provider-icon gemini">${ico('spark')}</span><strong>Gemini</strong><small>Your AI Studio API credits</small><span class="provider-tag">Easy to start</span></button><button class="provider-card ${p.provider==='ollama'?'chosen':''}" data-action="choose-provider" data-provider="ollama"><span class="provider-icon">${ico('local')}</span><strong>Local · Ollama</strong><small>Open weights on your computer</small><span class="provider-tag">No model API fee</span></button><button class="provider-card ${p.provider==='custom'?'chosen':''}" data-action="choose-provider" data-provider="custom"><span class="provider-icon">${ico('globe')}</span><strong>Other endpoint</strong><small>LM Studio or compatible API</small><span class="provider-tag">Bring your model</span></button></div>
${p.provider==='ollama'?`<div class="notice"><span>${ico('local')}</span><div><strong>A practical starting point for 16–32 GB RAM.</strong><p>Install Ollama, then pull <code>qwen3.5:9b</code>. Use <code>qwen3.5:4b</code> if memory is tight. Context size adds memory use; verify the writing before live sending.</p><a href="https://ollama.com/download" target="_blank" rel="noreferrer">Get Ollama ${ico('external')}</a> <a href="https://ollama.com/library/qwen3.5" target="_blank" rel="noreferrer">Model sizes ${ico('external')}</a><div class="local-model-controls">${button('Prepare 4B model','install-local','outline','data-model="qwen3.5:4b"')} ${button('Prepare 9B model','install-local','outline','data-model="qwen3.5:9b"')}</div><p>Once Ollama is installed and running, these buttons download weights if needed and create a 16K-context Pipeline model. Downloads can be several GB.</p></div></div>`:p.provider==='gemini'?`<div class="notice"><span>${ico('spark')}</span><div><strong>Use an AI Studio key from the project with your credits.</strong><p>Gemini 3.8 Flash is the current Flash default. Use Gemini 4 Argon for drafting and editing if you prefer; it requires paid-tier access. Current Gemini models use low thinking for these routine tasks to reduce latency and token use. Quotas and model availability depend on your project. Credits are managed by Google, not this app.</p><a href="https://aistudio.google.com/apikey" target="_blank" rel="noreferrer">Get an API key ${ico('external')}</a> <a href="https://ai.google.dev/gemini-api/docs/pricing" target="_blank" rel="noreferrer">Check current pricing ${ico('external')}</a></div></div>`:''}
${s.settings.environment_overrides.length?`<div class="notice compact">${ico('warning')}<p>Environment overrides are active: ${s.settings.environment_overrides.map(esc).join(', ')}. These take priority over saved UI values.</p></div>`:''}
<form id="model-form" class="form-stack"><input type="hidden" name="provider" value="${esc(p.provider)}"><div class="form-grid">${field('API endpoint','base_url',p.base_url,'url','required')}${field('Default model','default_model',p.default_model,'text','required list="model-options"')}<datalist id="model-options">${[...new Set([...(p.provider==='gemini'?['gemini-3.8-flash','gemini-4-argon']:[]),...state.models])].map(m=>`<option value="${esc(m)}">`).join('')}</datalist></div>${p.provider!=='ollama'?field('API key','api_key','','password',`autocomplete="new-password" placeholder="${s.settings.api_key_present&&s.settings.provider===p.provider?'Saved securely · leave blank to keep':'Paste your API key'}"`):'<p class="field-hint">Local Ollama does not need an API key. Nothing is uploaded to a cloud model.</p>'}${p.provider==='gemini'?`<div class="form-actions">${button('Use latest Flash everywhere','gemini-flash','outline')}${button('Use Argon for writing & editing','gemini-argon','outline')}</div><p class="field-hint">Suggested model IDs are starting points. List available models to check your project’s catalog. These buttons change the form; save to apply.</p>`:''}<details class="advanced"><summary>Choose models per task</summary><p>Leave blank to use the default. Every task stays on this same provider; there is no automatic cloud fallback.</p><div class="form-grid">${['research','qualify','classify','write','edit','ground','proposal'].map(task=>field(pretty(task)+' model','model_'+task,p.models?.[task]||'','text','list="model-options"')).join('')}</div></details>${p.provider==='ollama'?`<label class="check-field"><input type="checkbox" name="local_thinking" ${p.local_thinking?'checked':''}><span>Enable local model thinking.<small>Off for faster routine calls. May substantially increase latency and token generation.</small></span></label>`:''}<label class="check-field"><input type="checkbox" name="allow_cloud_email" ${p.allow_cloud_email?'checked':''}><span>Allow incoming customer correspondence to be processed by this cloud model.<small>Optional for local models. Needed for cloud reply classification and conversation-based drafts. Google’s free tier may use submitted content to improve its products; check the terms before sending private material.</small></span></label><div class="form-actions"><button class="btn primary" type="submit">Save model settings ${ico('check')}</button>${button('List available models','list-models','outline')}${button('Test connection','test-model','outline')}</div><p class="field-hint">The connection test uses a fictional prospect, counts as one model call, and never sends email.</p><div id="connection-result">${s.setup.model_tested?`<div class="connection-success">${ico('check')} Connection tested ${date(s.setup.model_tested_at)}. Review actual writing quality separately.</div>`:''}</div></form>${stepFooter()}`;}
function identitySetup(){const config=state.snapshot.campaigns[0]?.config||{};return `${setupTitle(2,'Put a real person behind the message.','These details go into your outreach. Use your actual identity and writing style. Add a postal address if you have one.')}<form id="identity-form" class="form-stack"><div class="form-grid">${field('Your name','sender_name',config.sender_name,'text','required autocomplete="name"')}${field('Sending Gmail address','sender_email',config.sender_email,'email','required autocomplete="email"')}</div>${area('Postal address · optional','postal_address',config.postal_address,'rows="2" placeholder="The real postal address to include in commercial outreach"')}<div class="notice compact">${ico('shield')}<p>A postal address is optional in Pipeline. US commercial outreach generally requires a valid postal address even when each email is manually reviewed. A registered PO Box or qualifying private mailbox can be used. <a href="https://www.ftc.gov/business-guidance/resources/can-spam-act-compliance-guide-business" target="_blank" rel="noreferrer">FTC guidance</a></p></div><div class="form-grid">${area('Approved facts about you · one per line','approved_facts',(config.approved_facts||[]).join('\n'),'rows="5" placeholder="Only credentials, experience, and results you can support."')}${area('Examples of your writing','voice_examples',(config.voice_examples||[]).join('\n\n---\n\n'),'rows="5" placeholder="Paste a couple of emails that sound like you. Separate examples with a line containing ---"')}</div>${field('Your working timezone','timezone',config.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone,'text','required placeholder="America/Los_Angeles"')}<div class="notice compact">${ico('shield')}<p>Saving applies these details to every campaign and invalidates old draft approvals. No credentials or achievements are invented.</p></div><button type="submit" class="btn primary">Save identity ${ico('check')}</button></form>${stepFooter()}`;}
function googleSetup(){const s=state.snapshot;return `${setupTitle(3,'Connect Google. Keep the setup simple.','Choose your account, approve access, and return here. Pipeline stores the connection on this computer.')}<div class="connection-card"><span class="provider-icon google">G</span><div><h3>Gmail & Google Calendar</h3><p>${s.google_account?.email?esc(s.google_account.email):s.setup.google_connected?'OAuth token saved on this computer':'Not connected yet'}</p></div>${badge(s.setup.google_connected?'Token saved':'Not connected',s.setup.google_connected?'green':'')}</div><section class="usage-section"><h3>${s.setup.google_connected?'Your Google account is connected':'One account. One connection.'}</h3><p>Connect Google → choose account → approve access. Google asks for Gmail read/draft/send and Calendar event/free-busy access. Connecting checks account identity and never sends a test email.</p>${button((s.setup.google_connected?'Reconnect Google':'Connect Google')+' '+ico('arrow'),'connect-google','primary',s.setup.google_client_uploaded?'':'disabled')}${!s.setup.google_client_uploaded?'<p class="field-hint">The app’s one-time OAuth registration must be saved below before connecting. You do not need a Gmail API key.</p>':''}</section><div class="notice compact">${ico('shield')}<div><strong>Only outreach conversations enter the workflow.</strong><p>Reply polling stays off until an outreach send attempt. After that, unrelated messages may be checked by headers to match replies, but only matching outreach threads or message references have their bodies retrieved. Unmatched delivery reports are left for manual inspection.</p><p>Google permissions are broader than this application rule. Related reply text reaches your configured cloud model only when cloud correspondence processing is enabled. Tokens stay in restricted local files.</p></div></div><details class="advanced"><summary>One-time app registration & connection settings</summary><p>This is developer setup, done once for this installation. Register a Desktop OAuth client in Google Cloud, enable Gmail and Calendar APIs, and allow your account as a test user if the app is in testing.</p><a href="https://console.cloud.google.com/auth/clients" target="_blank" rel="noreferrer">Google OAuth clients ${ico('external')}</a><form id="google-client-form" class="form-stack"><label class="file-field"><input type="file" name="client" accept="application/json,.json" required><span>${s.setup.google_client_uploaded?'An OAuth client is saved. Upload only to replace it.':'Select the Desktop OAuth client JSON'}</span></label><button type="submit" class="btn outline">Save client file</button></form><form id="google-client-json-form" class="form-stack">${area('Desktop OAuth client JSON','client_json','','required rows="3" autocomplete="off" placeholder="Paste the original Desktop OAuth JSON only if a file upload is unavailable."')}<button type="submit" class="btn outline">Save app registration</button></form><p class="field-hint">The client secret is saved with restricted permissions and never returned by the API. If Google keeps the app in testing, periodic reauthorization may be required.</p></details>${s.setup.google_connected?button('Disconnect this account','disconnect-google','ghost danger'):''}${stepFooter()}`;}
